    # Floyd-Warshall algorithm to detect cycles
    dist = [[float('inf')] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0

    # Map file names to indices
    file_to_index = {file: i for i, file in enumerate(files)}

    for file, k, imports in dependencies:
        for imp in imports:
            dist[file_to_index[file]][file_to_index[imp]] = 1

    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][k] < float('inf') and dist[k][j] < float('inf'):
                    dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j])

    # Find the shortest cycle
    shortest_cycle = None
    for i in range(n):
        if dist[i][i] != 0:
            cycle_length = dist[i][i]
            cycle = []
            current = i
